package main

import (
"fmt"
"bufio"
"strings"
)


func main() {
    scanner := bufio.NewScanner(strings.NewReader(""))
    scanner.Buffer(make([]byte, 0, 4), 8)
    count := 0
    for scanner.Scan() { count++ }
    if err := scanner.Err(); err != nil { fmt.Println("scan failed"); return }
    fmt.Println(count)
}

package main

import (
"fmt"
"encoding/json"
)

type Session struct { Minutes int `json:"minutes"` }
func main() {
    var session Session
    err := json.Unmarshal([]byte(`{"minutes":`), &session)
    if err != nil { fmt.Println("invalid JSON"); return }
    if session.Minutes < 1 || session.Minutes > 60 { fmt.Println("invalid minutes"); return }
    fmt.Println(session.Minutes)
}
